<script>
const q=s=>document.querySelector(s),qa=s=>document.querySelectorAll(s);q('#stock-search').addEventListener('input',e=>{const term=e.target.value.toLowerCase();let visible=0;qa('#stock-table tr[data-search]').forEach(row=>{const show=row.dataset.search.includes(term);row.hidden=!show;if(show)visible++});q('#no-search-results').classList.toggle('hidden',visible>0)});
const openMovement=button=>{const type=button.dataset.movement;q('#movement-form').action=`/stock-management/${button.dataset.id}/movement`;q('#movement-type').value=type;q('#movement-name').textContent=button.dataset.name;q('#movement-balance').textContent=button.dataset.quantity;q('#movement-quantity').value='';q('#movement-quantity').max=type==='out'?button.dataset.quantity:'';q('#movement-title').textContent=type==='in'?'Masuk Inventori (Stock In)':'Keluar Inventori (Stock Out)';q('#movement-submit').textContent=type==='in'?'Tambah Stok':'Tolak Stok';q('#movement-modal').classList.remove('hidden')};qa('[data-movement]').forEach(button=>button.addEventListener('click',()=>openMovement(button)));qa('[data-close-movement]').forEach(button=>button.addEventListener('click',()=>q('#movement-modal').classList.add('hidden')));
@if($isAdmin)const modal=q('#item-modal'),form=q('#item-form');qa('[data-open-modal]').forEach(button=>button.addEventListener('click',()=>{form.reset();form.action='{{ route('stock.store') }}';q('#item-method').value='';q('#item-modal-title').textContent='Tambah Barangan Baharu';modal.classList.remove('hidden')}));qa('[data-open-edit]').forEach(button=>button.addEventListener('click',()=>{const item=JSON.parse(button.dataset.openEdit);form.action=`/stock-management/${item.id}`;q('#item-method').value='PUT';q('#item-modal-title').textContent='Kemaskini Barangan';q('#item-sku').value=item.sku;q('#item-name').value=item.name;q('#item-category').value=item.category;q('#item-quantity').value=item.quantity;q('#item-minimum').value=item.reorder_level;q('#item-cost').value=item.cost_price;q('#item-price').value=item.selling_price;q('#item-description').value=item.description||'';modal.classList.remove('hidden')}));qa('[data-close-modal]').forEach(button=>button.addEventListener('click',()=>modal.classList.add('hidden')));@endif
@if($isAdmin)const memoModal=q('#memo-modal');q('[data-open-memo]').addEventListener('click',()=>memoModal.classList.remove('hidden'));qa('[data-close-memo]').forEach(button=>button.addEventListener('click',()=>memoModal.classList.add('hidden')));memoModal.addEventListener('click',event=>{if(event.target===memoModal)memoModal.classList.add('hidden')});@endif
</script>
